#' Isoform Usage per Group of Cells
#'
#' Plots the usage of the isoforms of a gene (fraction of the gene counts) in each group of cells, as
#' tested by \code{FindIsoforms}, optionally in each sample (replication of the changes).
#'
#' @param seurat_obj iDGE Seurat object generated by SCALPEL (features \code{gene***isoform}).
#' @param gene_in Gene name.
#' @param group_by Metadata column with the groups of cells.
#' @param sample_by Optional metadata column with the sample of each cell: usage in each sample shown as points.
#' @param groups Optional subset / order of the groups.
#' @param isoform_annotation Optional SCALPEL isoform annotation (directory \code{<outdir>/isoform} or
#'   \code{*.annots.gz} files) or GTF \code{GRanges}: isoforms ordered from the most proximal to the most
#'   distal 3' end.
#' @param min_usage Isoforms with a usage below this value in all the groups are merged in \code{"other"}. Default 0.05.
#' @param assay Seurat assay. Default \code{"RNA"}.
#'
#' @return A ggplot object: one bar per isoform and group (usage of all the cells of the group), points: usage in
#'   each sample, number of gene UMIs of each group in the legend.
#'
#' @examples
#' \dontrun{
#' plotUsage(idge, gene_in = "Reep1", group_by = "celltype", sample_by = "orig.ident",
#'           isoform_annotation = "results/isoform")
#' }
#'
#' @export
plotUsage <- function(
    seurat_obj,
    gene_in,
    group_by,
    sample_by = NULL,
    groups = NULL,
    isoform_annotation = NULL,
    min_usage = 0.05,
    assay = "RNA") {
  meta <- seurat_obj[[]]
  if (!(group_by %in% colnames(meta))) stop("Error: ", group_by, " not found in Seurat object !")
  feats <- grep(paste0("^", gene_in, "\\*\\*\\*"), rownames(seurat_obj), value = TRUE)
  if (length(feats) == 0) stop("No isoform of ", gene_in, " in the Seurat object")

  #- counts of the isoforms aggregated per group (and sample)...
  counts <- SeuratObject::LayerData(SeuratObject::JoinLayers(seurat_obj, assay = assay), assay = assay, layer = "counts")[feats, , drop = FALSE]
  key <- data.table::data.table(group = as.character(meta[[group_by]]), sample = if (is.null(sample_by)) "all" else as.character(meta[[sample_by]]))
  keep <- !is.na(key$group) & (is.null(groups) | key$group %in% groups)
  key <- key[keep]
  counts <- counts[, keep, drop = FALSE]
  id <- factor(paste(key$sample, key$group, sep = "\r"))
  agg <- as.matrix(counts %*% Matrix::sparseMatrix(i = seq_along(id), j = as.integer(id), x = 1, dims = c(length(id), nlevels(id))))
  colnames(agg) <- levels(id)
  tab <- data.table::as.data.table(reshape2::melt(agg, varnames = c("gene_tr", "id"), value.name = "counts"))
  tab[, c("sample", "group") := data.table::tstrsplit(as.character(id), "\r", fixed = TRUE)]
  tab[, transcript_name := sub(".*\\*\\*\\*", "", as.character(gene_tr))]
  tab[, `:=`(umis = sum(counts), usage = counts / pmax(sum(counts), 1e-12)), by = .(sample, group)]

  #- isoforms from the most proximal to the most distal 3' end...
  lv_tr <- sort(unique(tab$transcript_name))
  ends <- .isoform_ends(isoform_annotation)
  if (!is.null(ends)) {
    e <- ends[gene_name == gene_in & transcript_name %in% lv_tr]
    if (nrow(e) > 0) {
      e[, d := ifelse(strand == "+", three_end, -three_end)]
      lv_tr <- c(e[order(d)]$transcript_name, setdiff(lv_tr, e$transcript_name))
    }
  }
  #- minor isoforms (usage < min_usage in all the groups) merged in "other"...
  pool <- tab[, .(counts = sum(counts)), by = .(transcript_name, group)]
  pool[, usage := counts / pmax(sum(counts), 1e-12), by = group]
  major <- pool[, .(m = max(usage)), by = transcript_name][m >= min_usage]$transcript_name
  if (length(major) < length(lv_tr)) {
    lv_tr <- c(intersect(lv_tr, major), "other")
    tab[!(transcript_name %in% major), transcript_name := "other"]
    tab <- tab[, .(counts = sum(counts)), by = .(transcript_name, sample, group, umis)]
    tab[, usage := counts / pmax(umis, 1e-12)]
  }
  tab[, transcript_name := factor(transcript_name, levels = lv_tr)]
  tab[, group := factor(group, levels = if (is.null(groups)) sort(unique(group)) else groups)]
  #- bars: usage of the cells of all the samples; points: usage in each sample...
  pool <- tab[, .(counts = sum(counts)), by = .(transcript_name, group)]
  pool[, `:=`(umis = sum(counts), usage = counts / pmax(sum(counts), 1e-12)), by = group]
  lab <- unique(pool[, .(group, umis)])
  lab[, label := paste0(group, " (", round(umis), " UMIs)")]
  dodge <- ggplot2::position_dodge(width = .8)

  p <- ggplot2::ggplot(tab, ggplot2::aes(transcript_name, usage, fill = group)) +
    ggplot2::geom_col(data = pool, position = dodge, width = .75, color = "black", linewidth = .2, alpha = .85) +
    ggplot2::scale_y_continuous(limits = c(0, 1), breaks = seq(0, 1, .25), expand = ggplot2::expansion(mult = c(0, .03))) +
    ggplot2::scale_fill_manual(values = stats::setNames(.group_colors(nlevels(tab$group)), levels(tab$group)),
                               labels = lab$label[match(levels(tab$group), lab$group)], name = group_by) +
    ggplot2::xlab("isoform (proximal -> distal 3' end)") +
    ggplot2::ylab("isoform usage (fraction of gene UMIs)") +
    ggplot2::ggtitle(gene_in) +
    ggplot2::theme_bw(base_size = 13) +
    ggplot2::theme(panel.grid.major.x = ggplot2::element_blank(), plot.title = ggplot2::element_text(face = "bold.italic"))
  if (!is.null(sample_by)) {
    p <- p + ggplot2::geom_point(ggplot2::aes(shape = sample, group = group), position = dodge, size = 2.2, fill = "white", stroke = .6) +
      ggplot2::scale_shape_manual(values = c(21:25, 0:14)[seq_along(unique(tab$sample))], name = sample_by)
  }
  return(p)
}
